def register_start_list(names):
    """Deduplicate case-insensitively; keep first spelling."""
    pass

exercise.solution:
def register_start_list(names):
    seen = set()
    out = []
    for n in names:
        key = n.lower()          # canonical comparison key
        if key not in seen:
            seen.add(key)
            out.append(n)        # original spelling kept
    return out

